def gau(u,off,A,u0,s,sl): return off+sl*(u-u0)+A*np.exp(-(u-u0)**2/(2*s*s))
def pv(u,off,A,u0,g,s,eta,sl):
    L=g*g/((u-u0)**2+g*g); G=np.exp(-(u-u0)**2/(2*s*s)); return off+sl*(u-u0)+A*(eta*L+(1-eta)*G)
def lor0(u,off,A,u0,g): return off+A*g*g/((u-u0)**2+g*g)
def gau0(u,off,A,u0,s): return off+A*np.exp(-(u-u0)**2/(2*s*s))

